<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$db=Database::connection();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$d=['categorie_id'=>'','code'=>'','libelle'=>'','type_reponse'=>'texte','options_json'=>'','obligatoire'=>1,'ordre_affichage'=>1,'statut'=>'active'];$errors=[];if($id){$s=$db->prepare('SELECT * FROM questions WHERE id=?');$s->execute([$id]);$d=$s->fetch()?:exit('Question introuvable.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['categorie_id','code','libelle','type_reponse','options_json','ordre_affichage','statut'] as $f)$d[$f]=trim((string)($_POST[$f]??''));$d['obligatoire']=isset($_POST['obligatoire'])?1:0;if(!(int)$d['categorie_id']||$d['code']===''||$d['libelle']==='')$errors[]='Branche, code et question sont obligatoires.';$opts=null;if($d['type_reponse']==='liste'){$items=array_values(array_filter(array_map('trim',explode(',',(string)$d['options_json']))));if(count($items)<2)$errors[]='Indiquez au moins deux options séparées par des virgules.';else $opts=json_encode($items,JSON_UNESCAPED_UNICODE);}if(!$errors){$v=[(int)$d['categorie_id'],strtoupper($d['code']),$d['libelle'],$d['type_reponse'],$opts,$d['obligatoire'],max(1,(int)$d['ordre_affichage']),$d['statut']];try{if($id){$v[]=$id;$db->prepare('UPDATE questions SET categorie_id=?,code=?,libelle=?,type_reponse=?,options_json=?,obligatoire=?,ordre_affichage=?,statut=? WHERE id=?')->execute($v);}else{$db->prepare('INSERT INTO questions(categorie_id,code,libelle,type_reponse,options_json,obligatoire,ordre_affichage,statut) VALUES(?,?,?,?,?,?,?,?)')->execute($v);$id=(int)$db->lastInsertId();}audit('ENREGISTREMENT','question',$id);flash('success','Question enregistrée.');redirect('questions/index.php');}catch(PDOException){$errors[]='Code déjà utilisé ou valeur incorrecte.';}}}
if($id&&$d['type_reponse']==='liste'&&$d['options_json']){$decoded=json_decode((string)$d['options_json'],true);if(is_array($decoded))$d['options_json']=implode(', ',$decoded);}$categories=$db->query('SELECT id,libelle FROM categories_risque ORDER BY libelle')->fetchAll();$title=$id?'Modifier la question':'Nouvelle question';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell"><div class="page-heading"><h1 class="h3"><?= e($title) ?></h1><a class="btn btn-outline-secondary" href="index.php">Retour</a></div><?php if($errors): ?><div class="alert alert-danger"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" class="card card-body"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Branche *</label><select class="form-select" name="categorie_id" required><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (int)$d['categorie_id']==(int)$c['id']?'selected':'' ?>><?= e($c['libelle']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><label class="form-label">Code *</label><input class="form-control" name="code" value="<?= e($d['code']) ?>" required></div><div class="col-md-3"><label class="form-label">Ordre</label><input type="number" min="1" class="form-control" name="ordre_affichage" value="<?= e((string)$d['ordre_affichage']) ?>"></div><div class="col-12"><label class="form-label">Question *</label><input class="form-control" name="libelle" value="<?= e($d['libelle']) ?>" required></div><div class="col-md-6"><label class="form-label">Type de réponse</label><select class="form-select" id="questionType" name="type_reponse"><?php foreach(['texte','nombre','date','booleen','liste'] as $t): ?><option value="<?= $t ?>" <?= $d['type_reponse']===$t?'selected':'' ?>><?= ucfirst($t) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Options de liste</label><input class="form-control" name="options_json" value="<?= e((string)$d['options_json']) ?>" placeholder="Option 1, Option 2, Option 3"><div class="form-text">Uniquement pour le type Liste.</div></div><div class="col-md-6"><label class="form-label">Statut</label><select class="form-select" name="statut"><option value="active" <?= $d['statut']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $d['statut']==='inactive'?'selected':'' ?>>Inactive</option></select></div><div class="col-md-6 d-flex align-items-end"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="obligatoire" id="obligatoire" <?= $d['obligatoire']?'checked':'' ?>><label class="form-check-label" for="obligatoire">Réponse obligatoire</label></div></div></div><div class="text-end mt-4"><button class="btn btn-primary">Enregistrer</button></div></form></div><?php require __DIR__.'/../../includes/footer.php'; ?>
